#include <vector>
#include <queue>
#include <utility>

using namespace std;

struct Road {
    int destination, length;
};

struct Edge {
    int a, b, l;
    Edge(int a_, int b_, int l_) : a(a_), b(b_), l(l_) {}
};

int main() {
    int n, m, k, a, b, l, s;
    vector<Edge> edges;
    vector<vector<Road>> towns(3001);
    int len[3001];
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> qu;
    const int inf = 1e9;

    scanf("%d %d %d", &n, &m, &k);
    while (m--) {
        scanf("%d %d %d", &a, &b, &l);
        edges.emplace_back(a, b, l);
        towns[a].push_back({b, l});
        towns[b].push_back({a, l});
    }

    while (k--) {
        scanf("%d", &s);
        qu.push({0, s});
    }

    fill(len, len + n + 1, -1);
    while (!qu.empty()) {
        auto pi = qu.top();
        qu.pop();

        if (len[pi.second] == -1) {
            len[pi.second] = pi.first;
            for (const auto& road : towns[pi.second]) {
                qu.push({pi.first + road.length, road.destination});
            }
        }
    }

    s = 0;
    for (const auto& edge : edges) {
        s = max(max(s, len[edge.a]), max(len[edge.b], (len[edge.b] + edge.l - len[edge.a] + 1) / 2 + len[edge.a]));
    }

    printf("%d\n", s);
}

