    road(int a_, int b_, int l_) : a(a_), b(b_), l(l_) {}
};

typedef pair<int, int> pii;

int main() {
    int n, m, k, a, b, l, s;
    vector<road> rd;
    vector<pii> town[3001];
    vector<int> len(3001, numeric_limits<int>::max()); // Use vector with max int
    priority_queue<pii, vector<pii>, greater<pii>> qu;

    cin >> n >> m >> k;
    for (int i = 0; i < m; ++i) {
        cin >> a >> b >> l;
        rd.emplace_back(a, b, l); // Use emplace_back for efficiency
        town[a].emplace_back(b, l); // Use emplace_back for efficiency
        town[b].emplace_back(a, l); // Use emplace_back for efficiency
    }

