        pii pi = qu.top();
        qu.pop();
        if (pi.first > len[pi.second]) continue; // Early exit for already processed nodes

        for (const auto& it : town[pi.second]) {
            int new_length = pi.first + it.second;
            if (new_length < len[it.first]) {
                len[it.first] = new_length;
